      textoFiltro,
      categoriaFiltro,
      libros,
      categoriasDisponibles,
      librosFiltrados,
      handleAgregarLibro,
      handleEliminarLibro,
      ref,
      computed,
      Libro,
      FormularioLibro,
      get libroStore() {
        return libroStore;
      },
      get agregarLibro() {
        return agregarLibro;
      },
      get eliminarLibro() {
        return eliminarLibro;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
